function updateClock() {
  const now = new Date();
  let hours = now.getHours();
  let minutes = now.getMinutes();
  let seconds = now.getSeconds();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')} ${ampm}`;
  document.getElementById('currentTime').textContent = timeStr;
}

setInterval(updateClock, 1000);
updateClock();

let alarms = [];

function addAlarm() {
  const time = document.getElementById('alarmTime').value;
  const label = document.getElementById('alarmLabel').value || 'Alarm';
  if (!time) return;
  alarms.push({ time, label, active: true });
  renderAlarms();
}

function renderAlarms() {
  const list = document.getElementById('alarmList');
  list.innerHTML = '';
  alarms.forEach((alarm, index) => {
    const li = document.createElement('li');
    li.innerHTML = `<span>${alarm.label} - ${alarm.time}</span>
      <button onclick="deleteAlarm(${index})">Delete</button>`;
    list.appendChild(li);
  });
}

